    length = len(n_str)

    # Check if the last two digits form a number divisible by 25
    if int(n_str[-2:]) % 25 == 0:
        return 0

    # If the number ends with 0, we need to find another 0 to swap
    if n_str[-1] == '0':
        for i in range(length-2, -1, -1):
            if n_str[i] == '0' and n_str[i+1] != '0':
                return length - i - 2

    # If the number does not end with 0, we need to find a suitable pair to swap
    pairs = [(i, j) for i in range(length) for j in range(i+1, length) if n_str[j] == '0' or n_str[j] in ['5', '0'] and n_str[(j+1)%length] in ['5', '0']]
    if not pairs:
        return -1

    min_moves = float('inf')
    for i, j in pairs:
        if j > i + 1:
            moves = length - j + i
        else:
            moves = length - j + i + 1

        if n_str[i] == '0' and n_str[i+1] != '0':
            moves -= 1

        min_moves = min(min_moves, moves)

    return min_moves

