        if digits[i] == 0 and pos_0[0] == -1:
            pos_0[0] = i
        elif digits[i] == 0 and pos_0[0] != -1:
            pos_0[1] = i
        if digits[i] == 5 and pos_5[0] == -1:
            pos_5[0] = i
        elif digits[i] == 5 and pos_5[0] != -1:
            pos_5[1] = i

    # If there is only one 0 and one 5, check if we can form a valid pair
    if pos_0[0] != -1 and pos_5[0] != -1:
        min_moves = float('inf')
        if pos_0[0] < pos_5[0]:
            min_moves = min(min_moves, pos_5[0] - pos_0[0] - 1 + pos_0[0])
            if pos_0[1] != -1:
                min_moves = min(min_moves, pos_5[0] - pos_0[1] - 1 + pos_0[1])
        else:
            min_moves = min(min_moves, pos_5[1] - pos_0[0] - 1 + pos_0[0])
